mapper.select:
select tr.id, tr.org_id as orgId, tr.type as firstVisit, tr.patient_id as patientId, tr.appointment_id as appointmentId, tr.registered_id as registeredId, tr.dentist_id as treatDentistId, tr.status as treatmentStatus, DATE_FORMAT(tr.crt_time, '%Y-%m-%d') as treatDate, DATE_FORMAT(tr.treat_start_time, '%H:%i') as treatStartTime, DATE_FORMAT(tr.treat_end_time, '%H:%i') as treatEndTime, tr.medical_record_completed as medicalRecordCompleted from treatment_record tr
and tr.id = #{queryForm.id}
and tr.org_id = #{queryForm.orgId}
and DATE_FORMAT(tr.crt_time, '%Y-%m-%d') = DATE_FORMAT(#{queryForm.currentDate}, '%Y-%m-%d')
and tr.status in
#{item}
and tr.dentist_id = #{queryForm.dentistId}
and tr.inservice = #{queryForm.inservice}
order by tr.id desc

SELECT tr.id AS treatmentRecordId, tr.org_id AS orgId, DATE_FORMAT( tr.treat_start_time, '%Y-%m-%d' ) AS treatmentDate, tr.dentist_id AS dentistId, tr.type AS firstVisit, tr.`status` AS treatmentStatus, tr.appointment_id as appointmentId, tr.registered_id as registeredId, ord.id as orderRecordId, ord.total_amount as originalPrice, br.id as billRecordId, br.actual_receivable_amount as actualReceivableAmount, br.debt_amount as debtAmount FROM treatment_record tr LEFT JOIN order_record ord on ord.inservice = 1 and tr.id = ord.treatment_record_id LEFT JOIN bill_record br on br.inservice = 1 and tr.id = br.treatment_record_id
and tr.patient_id = #{queryForm.patientId}
and DATE_FORMAT(tr.treat_start_time,'%Y-%m-%d') >= #{queryForm.startDate}
and DATE_FORMAT(tr.treat_start_time,'%Y-%m-%d') <= #{queryForm.endDate}
and tr.org_id in
#{item}
and tr.status in
#{item}
ORDER BY tr.treat_start_time DESC

select tr.*, date_format(a.treat_start_time,'%Y-%m-%d') as last_treatment_date from treatment_record tr left join treatment_record a on a.patient_id = tr.patient_id where tr.id in
#{item}
order by tr.treat_start_time ,a.treat_start_time desc

SELECT r.patient_id AS patientId, r.dentist_id AS dentistId, r.dept_room_id AS deptRoomId, r.crt_time AS crtTime FROM registered r
r.patient_id = #{patientId}
ORDER BY r.crt_time DESC LIMIT 1

SELECT DATE_FORMAT(a.crt_time,'%Y-%m-%d') as currentDate, COUNT(a.id) as `count` FROM( SELECT tr.id, DATE_FORMAT(tr.crt_time,'%Y-%m-%d') as crt_time FROM `treatment_record` tr
and tr.dentist_id = #{dentistId}
and date_format(tr.crt_time,'%Y-%m-%d') BETWEEN date_format(#{startDate},'%Y-%m-%d') AND date_format(#{endDate},'%Y-%m-%d')
and org_id = #{orgId}
) a GROUP BY a.crt_time
